// Pluggable text-to-speech providers for article narration.
//
// Why this exists
// ───────────────
// Narration used to be generated by exactly one hard-coded call to
// `fal.subscribe('fal-ai/orpheus-tts', ...)` inlined into
// scripts/publish-article-motion-video.mjs. That produced two failures at once:
//
//   1. Single point of failure. When the FAL account hit
//      `403 User is locked. Reason: Exhausted balance.` the narration pipeline
//      could not run AT ALL. There was no second provider and no way to select
//      one, so an outage at one vendor took the whole publication path down.
//
//   2. Silent content corruption. Orpheus degrades on the ~2000-character
//      single-call input the publisher sent: the published films delivered only
//      29-67% of the intended script, and one contained roughly 25 s of
//      hallucinated babble (confirmed by two independent ASR models). Nothing
//      in the pipeline compared what came back against what was sent, so a
//      track that dropped half its script was written straight to disk,
//      rendered into an MP4, and published.
//
// This module fixes (1) by making the provider selectable. `verify-narration.mjs`
// fixes (2) by measuring every returned track before it is accepted.
//
// Selection
// ─────────
//   LUPINE_TTS_PROVIDER=minimax   (default)
//   LUPINE_TTS_PROVIDER=fal
//
// The default is `minimax` because the FAL account is locked. The FAL path is
// kept fully working — not deleted — so it can be selected again the moment
// the account is restored, with no code change.
//
// Measured behaviour at the input size that breaks Orpheus (2051 characters /
// 312 words): MiniMax `speech-2.8-hd` returned 125.86 s = 149 wpm = 97% of the
// expected length, with no truncation. That is why this is primarily a provider
// swap rather than a chunking rewrite — though the publisher chunks anyway,
// because per-chunk durations are what let captions be timed to the real audio
// without a speech-to-text pass.

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');

export const DEFAULT_PROVIDER = 'minimax';

/** Provider-neutral narrator voice, per provider. */
const NARRATOR_VOICE = {
  minimax: 'English_expressive_narrator',
  fal: 'dan',
};

// ── credential loading ───────────────────────────────────────────────────────

function readTrimmed(file) {
  return fs.existsSync(file) ? fs.readFileSync(file, 'utf8').trim() : undefined;
}

function loadFalKey() {
  return process.env.FAL_KEY || readTrimmed(path.join(ROOT, '.keys', 'fal-key'));
}

// MiniMax credentials come from the Hermes OAuth record on this machine. An
// explicit env var or repo key file wins, so CI or another operator can supply
// a token without a Hermes install.
function loadMiniMaxToken() {
  if (process.env.MINIMAX_API_KEY) return process.env.MINIMAX_API_KEY;
  const keyFile = readTrimmed(path.join(ROOT, '.keys', 'minimax-key'));
  if (keyFile) return keyFile;
  const authPath = process.env.HERMES_AUTH_PATH || path.join(os.homedir(), '.hermes', 'auth.json');
  if (!fs.existsSync(authPath)) return undefined;
  try {
    const auth = JSON.parse(fs.readFileSync(authPath, 'utf8'));
    return auth?.providers?.['minimax-oauth']?.access_token;
  } catch {
    return undefined;
  }
}

// ── providers ────────────────────────────────────────────────────────────────
//
// Each provider exposes:
//   id            stable identifier written into the narration manifest
//   model         model identifier, for provenance
//   extension     container the provider returns ('mp3' | 'wav')
//   defaultVoice  narrator voice id in that provider's namespace
//   credentials() the token, or undefined when unavailable
//   hint          what to do when credentials() is undefined
//   synthesize({ text, voice, outPath })  writes audio, returns provider metadata

const MINIMAX_ENDPOINT = 'https://api.minimax.io/v1/t2a_v2';

const minimax = {
  id: 'minimax',
  model: 'speech-2.8-hd',
  extension: 'mp3',
  defaultVoice: NARRATOR_VOICE.minimax,
  credentials: loadMiniMaxToken,
  hint: 'Set MINIMAX_API_KEY, create .keys/minimax-key, or provide ~/.hermes/auth.json with a minimax-oauth access_token.',
  async synthesize({ text, voice, outPath }) {
    const token = loadMiniMaxToken();
    const res = await fetch(MINIMAX_ENDPOINT, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: minimax.model,
        text,
        stream: false,
        language_boost: 'auto',
        output_format: 'hex',
        voice_setting: { voice_id: voice, speed: 1.0, vol: 1.0, pitch: 0 },
        audio_setting: { sample_rate: 32000, bitrate: 128000, format: 'mp3', channel: 1 },
      }),
    });
    if (!res.ok) {
      throw new Error(`MiniMax TTS HTTP ${res.status}: ${(await res.text()).slice(0, 400)}`);
    }
    const data = await res.json();
    const status = data?.base_resp?.status_code;
    if (status !== 0) {
      throw new Error(`MiniMax TTS error: ${JSON.stringify(data?.base_resp ?? data).slice(0, 400)}`);
    }
    const hex = data?.data?.audio;
    if (!hex) throw new Error(`MiniMax TTS returned no audio: ${JSON.stringify(data).slice(0, 400)}`);
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, Buffer.from(hex, 'hex'));
    // `audio_length` is the provider's own duration in ms. It is recorded for
    // provenance but NEVER trusted as the verification measurement — that is
    // taken from the decoded file by ffprobe, because a provider reporting a
    // duration it did not deliver is exactly the failure mode being guarded.
    return {
      provider: minimax.id,
      model: minimax.model,
      voice,
      reportedMs: data?.extra_info?.audio_length ?? null,
    };
  },
};

const falProvider = {
  id: 'fal',
  model: 'fal-ai/orpheus-tts',
  extension: 'wav',
  defaultVoice: NARRATOR_VOICE.fal,
  credentials: loadFalKey,
  hint: 'Set FAL_KEY or create .keys/fal-key. Note: the FAL account was locked with "Exhausted balance" — check the balance before selecting this provider.',
  async synthesize({ text, voice, outPath }) {
    const key = loadFalKey();
    process.env.FAL_KEY = key;
    // Imported lazily so a missing/locked FAL setup cannot break the default
    // MiniMax path at module load time.
    const { fal } = await import('@fal-ai/client');
    let result;
    try {
      result = await fal.subscribe(falProvider.model, {
        input: { text, voice, temperature: 0.6, repetition_penalty: 1.2 },
        logs: true,
      });
    } catch (e) {
      // The FAL client throws bare `Error: Forbidden` for an account lock, which
      // is indistinguishable from a bad key. Surface the status and body so the
      // operator can tell "out of balance" from "wrong credential" and switch
      // providers instead of debugging the key.
      const status = e?.status ?? e?.response?.status;
      const body = e?.body ? JSON.stringify(e.body).slice(0, 300) : '';
      throw new Error(
        `FAL Orpheus request failed${status ? ` (HTTP ${status})` : ''}: ${e.message}${body ? ` — ${body}` : ''}. `
        + `A 403 here is usually "User is locked. Reason: Exhausted balance." — `
        + `check the FAL balance, or run with LUPINE_TTS_PROVIDER=minimax.`,
      );
    }
    const url = result?.data?.audio?.url;
    if (!url) {
      throw new Error(`FAL Orpheus returned no audio URL: ${JSON.stringify(result?.data).slice(0, 400)}`);
    }
    const res = await fetch(url);
    if (!res.ok) throw new Error(`FAL audio download HTTP ${res.status}`);
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, Buffer.from(await res.arrayBuffer()));
    return { provider: falProvider.id, model: falProvider.model, voice, reportedMs: null };
  },
};

export const PROVIDERS = { minimax, fal: falProvider };

/**
 * Resolve a TTS provider by name, falling back to LUPINE_TTS_PROVIDER and then
 * to the default. Throws a specific, actionable error when the provider is
 * unknown or its credentials are missing — never a generic failure, because
 * "narration did not generate" was previously indistinguishable from
 * "narration generated badly".
 */
export function resolveProvider(name) {
  const id = (name || process.env.LUPINE_TTS_PROVIDER || DEFAULT_PROVIDER).toLowerCase();
  const provider = PROVIDERS[id];
  if (!provider) {
    throw new Error(
      `Unknown TTS provider "${id}". Available: ${Object.keys(PROVIDERS).join(', ')} `
      + `(set LUPINE_TTS_PROVIDER or pass --tts-provider).`,
    );
  }
  if (!provider.credentials()) {
    const others = Object.values(PROVIDERS)
      .filter((p) => p.id !== id && p.credentials())
      .map((p) => p.id);
    const alt = others.length
      ? ` Provider(s) with usable credentials right now: ${others.join(', ')} — select with LUPINE_TTS_PROVIDER=${others[0]}.`
      : ' No other provider has usable credentials either.';
    throw new Error(`TTS provider "${id}" has no credentials. ${provider.hint}${alt}`);
  }
  return provider;
}

/** Narrator voice for a provider, translating the legacy FAL voice name. */
export function narratorVoice(provider, requested) {
  if (!requested || requested === 'dan' || requested === 'default') return provider.defaultVoice;
  return requested;
}
